package com.example.app07.application.service; import com.example.app07.domain.entity.Expense; import com.example.app07.infrastructure.repository.ExpenseRepository; import java.util.List; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service public class ExpenseService { private final ExpenseRepository repository; public ExpenseService(ExpenseRepository repository) { this.repository=repository; } @Transactional(readOnly=true) public List<Expense> list() { return repository.findAll(); } @Transactional public Expense create(Expense e) { return repository.save(e); } }
